from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those groups into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    def is_balanced(s: str) -> bool:
        """Check if the parentheses in s are balanced."""
        count = 0
        for c in s:
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count < 0:
                    return False
        return count == 0

    def find_group_start(s: str) -> int:
        """Find the starting index of the first unbalanced parenthesis group in s."""
        count = 0
        for i, c in enumerate(s):
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count < 0:
                    return i
        return len(s)

    def find_group_end(s: str, start: int) -> int:
        """Find the ending index of the first unbalanced parenthesis group in s, after the given start index."""
        count = 0
        for i in range(start, len(s)):
            if s[i] == '(':
                count += 1
            elif s[i] == ')':
                count -= 1
                if count == 0:
                    return i
        return len(s)

    result = []
    n = len(paren_string)
    i = 0
    while i < n:
        start = find_group_start(paren_string[i:])
        end = find_group_end(paren_string[i:], start)
        group = paren_string[i:i + end - start]
        i += end - start
        result.append(group)

    return result


# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Split the input string into a list of characters
    chars = test.split()
    char_count = {}

    # Count occurrences of each character
    for char in chars:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum occurrence
    max_occurrence = max(char_count.values(), default=0)

    # Filter the dictionary to only include characters that occur max_occurrence times
    result = {char: count for char, count in char_count.items() if count == max_occurrence}

    return result

def match_parens(lst):
    '''
    This function checks if it's possible to concatenate two given strings
    (each containing only '(' and ')' characters) in any order to form a
    balanced string.
    A string is considered balanced if all parentheses are properly closed and opened.
    Returns 'Yes' if a balanced string can be formed, 'No' otherwise.
    '''

    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Check both possible concatenations
    for s in [lst[0] + lst[1], lst[1] + lst[0]]:
        if is_balanced(s):
            return 'Yes'
    return 'No'


# Test cases
print(match_parens(['()(', ')']))  # Expected output: 'Yes'
print(match_parens([')', ')']))    # Expected output: 'No'

def split_words(txt):
    """
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    """
    # Check for commas
    if ',' in txt:
        return txt.split(',')
    # Check for spaces
    elif ' ' in txt:
        return txt.split(' ')
    else:
        # Count characters with odd positions in the alphabet
        return sum(1 for c in txt if (ord(c) - ord('a')) % 2 == 0)


# Test cases
print(split_words("Hello world!"))  # ➞ ["Hello", "world!"]
print(split_words("Hello,world!"))  # ➞ ["Hello", "world!"]
print(split_words("abcdef"))  # ➞ 3

def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True


def words_in_sentence(sentence):
    """
    Extracts words from the input sentence where the length of each word is a prime number.
    The extracted words are returned in the same order as they appear in the original sentence.
    """
    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)


