print(sum_product([1, 2, 3, 4]))  # Expected output: (10, 24)

def numerical_letter_grade(grades):
    """Converts a list of GPAs into a list of letter grades based on the provided grading scale.

    Args:
        grades (list): A list of floating point numbers representing the GPAs.

    Returns:
        list: A list of strings representing the corresponding letter grades.
    """
    letter_grades = []
    for gpa in grades:
        if gpa == 4.0:
            letter_grades.append('A+')
        elif gpa > 3.7:
            letter_grades.append('A')
        elif gpa > 3.3:
            letter_grades.append('A-')
        elif gpa > 3.0:
            letter_grades.append('B+')
        elif gpa > 2.7:
            letter_grades.append('B')
        elif gpa > 2.3:
            letter_grades.append('B-')
        elif gpa > 2.0:
            letter_grades.append('C+')
        elif gpa > 1.7:
            letter_grades.append('C')
        elif gpa > 1.3:
            letter_grades.append('C-')
        elif gpa > 1.0:
            letter_grades.append('D+')
        elif gpa > 0.7:
            letter_grades.append('D')
        else:
            letter_grades.append('E')
    return letter_grades


# Example usage
print(numerical_letter_grade([4.0, 3, 1.7, 2, 3.5]))

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    """Find the largest prime value in the list and return the sum of its digits.
    Examples provided in the docstring.
    """
    max_prime = -1
    for num in lst:
        if is_prime(num):
            max_prime = max(max_prime, num)

    if max_prime == -1:
        return 0  # No prime numbers found

    digit_sum = sum(int(digit) for digit in str(max_prime))
    return digit_sum

